def fruit_distribution(s, n):
    apples = int(s.split(' ')[0])
    oranges = int(s.split(' ')[-2])

    total_fruits = apples + oranges
    mangoes = n - total_fruits

    if apples == 0:
        mangoes += oranges
    elif oranges == 0:
        mangoes += apples

    return mangoes

